import json
from pathlib import Path
R=json.load(open('final_results.json'))
X='((p-patm)/patm)'
O='Min(1, Max(0, 1-valve/vmax))'
C=f'cf*(1+shape)*{O}**expo/(1+shape*{O}**expo)'
H={0:f'{X}/({X}**2+delta**2)**((1-power)/2)',1:f'2*{X}/(delta+sqrt(delta**2+4*Abs({X})))'}
ratio='Max(rcrit, Min(p, patm)/Max(p, patm))'
H[2]=f'sign({X})*Max(p, patm)/patm*sqrt(Max(0, {ratio}**(2/gam)-{ratio}**((gam+1)/gam)))*sqrt(Abs({X})/(Abs({X})+delta))'
units=['bar*min/(s*L)','bar/s','-','-','1/s','-'];names=['ain','cf','expo','shape','rate','power']
unitwords=[' bar*min/(s*L)',' bar/s','','',' 1/s','']
def vals(v):return ', '.join(f'`{names[i]} = {x:.16g}`{unitwords[i]}' for i,x in enumerate(v))
def param(name,value,unit,typ,desc,eq=None):
 d=dict(name=name,value=float(value),unit=unit,type=typ,description=desc)
 if eq is not None:d['equation']=eq
 return d
for label,r in R.items():
 k=r['kind'];t=r['parameters'];expr=f'ain*flow - ({C})*({H[k]})'
 desc=[
 'Inlet conversion gain `ain`: pressure rate per measured `flow`; jointly fitted in all three steps in fit_final.py. It combines gas inventory/capacitance and the mass-flow reference convention, not a separately measured volume.',
 'Full-open outlet scale `cf` in bar/s for the dimensionless pressure-driving law. Jointly fitted in all three steps in fit_final.py; normalization makes the aperture factor equal to unity at `valve = 0` percent.',
 'Positive aperture exponent `expo`, jointly fitted in all three steps in fit_final.py. It describes the unknown actuator-to-effective-opening characteristic; it is not a measured valve geometry.',
 'Nonnegative series-loss shape `shape`, jointly fitted in all three steps in fit_final.py. The rational aperture law saturates as the opening grows, representing an empirical approximation of fixed pipe/outlet resistance in series with the controlled restriction.',
 'Full-open atmospheric small-signal relaxation rate `rate`, jointly fitted in all three steps in fit_final.py. The upper bound of `rate = 0.5` 1/s was chosen for stable five-second RK4 relaxation, not inferred as a known physical constant; the final estimate reaches that bound.',
 'Far-from-atmosphere pressure exponent `power`, jointly fitted in all three steps in fit_final.py. It interpolates empirical fractional pressure-loss behavior and is not assumed to equal an isentropic exponent.'
 ]
 parameters=[param(names[i],v,units[i],'fitted',desc[i]) for i,v in enumerate(t)]
 parameters += [param('patm',1.,'bar','fixed','Atmospheric reference `patm = 1` bar, taken from the approximately one-bar equilibrium in TASK.md and deliberately not estimated; it fixes the equilibrium rather than absorbing pressure-sensor bias.'),param('vmax',100.,'%','fixed','Fully closed calibration `vmax = 100` percent, given in TASK.md; it normalizes valve closure to a dimensionless opening.')]
 eq={0:'(cf/(patm*rate))**(1/(1-power))',1:'cf/(patm*rate)',2:'(2/gam)*(cf/(patm*rate))**2'}[k]
 parameters += [param('delta',r['smoothing'],'-','tied','Dimensionless near-atmospheric pressure scale `delta`; computed from the outlet scale and the fitted atmospheric relaxation rate. This gives a finite near-equilibrium slope rather than a singular fractional-power slope.',eq)]
 if k==2:
  parameters += [param('gam',1.4,'-','fixed','Dry-air ideal-gas heat-capacity ratio `gam = 1.4`, assumed constant; a standard approximation, also used by the NASA Glenn isentropic-flow treatment checked during this round.'),param('rcrit',(2/2.4)**3.5,'-','tied','Critical downstream/upstream pressure ratio `rcrit` at sonic choking, from the ideal isentropic-nozzle relation.','(2/(gam+1))**(gam/(gam-1))')]
 criterion='Stage 1 minimizes the unweighted sum of squared differences between predicted `dp` and recorded `dp`, in (bar/s)**2, for initialization only. Stage 2 minimizes the unweighted sum of squared free-running `p` simulation errors on training, in bar**2. Stage 3, which determines every delivered fitted parameter, minimizes the same pressure-error sum over both available trajectories. Pressure simulation is the intended use, so derivative least squares alone was not used for final values. Each simulation uses classical RK4 with one step of 5 s and inputs held at row k from sample k to sample k+1; no measured-state replacement follows initialization.'
 data='Stage 1: all 1452 rows of data/train.csv. Stage 2: the single training trajectory, initialized at its first measured `p`, scoring rows 1 through 1451 with zero-based indexing. Stage 3: data/train.csv and data/val.csv as two separately initialized trajectories, scoring respectively rows 1 through 1451 and 1 through 1453. These are 2904 pressure errors. No rows were removed and no internal resets were inserted. Validation first assessed training-only fits and guided structural choices, then was deliberately included in the final refit to improve parameter coverage; final validation RMSE is not an independent generalization estimate. No unavailable test data were used.'
 boundtext='; '.join(f'`{l:.16g} <= {names[i]} <= {h:.16g}`{unitwords[i]}' for i,(l,h) in enumerate(zip(*r['bounds'])))
 method=('Bound-constrained nonlinear least squares, Trust Region Reflective algorithm, scipy.optimize.least_squares with method="trf" (default), loss="linear", two-point finite-difference Jacobian, x_scale="jac", max_nfev=600 per stage, and ftol=xtol=gtol=1e-10. Reference: SciPy least_squares official documentation, checked during this round. This algorithm permits positive gains and bounded relaxation rates; ordinary linear least squares cannot estimate the nonlinear exponents/shape. All independent fitted parameters were estimated jointly within each of the three sequential stages; `delta` and, where present, `rcrit` were always computed by the tie equations, never independently optimized. No random numbers or seeds were used. Stage-1 starting values: '+vals(r['start'])+'. They were rounded approximations from the exploratory mass-balance fits, chosen to lie on physically meaningful scales and within the bounds. Stage-2 starting values (the stage-1 solution): '+vals(r['derivative_fit'])+'. Stage-3 starting values (the stage-2 solution): '+vals(r['training_fit'])+'. Bounds: '+boundtext+'. Positive lower bounds prevent nonphysical negative gains and degenerate zero conductance; aperture/exponent and series-shape bounds are broad empirical search limits, not independently measured quantities. The rate upper bound avoids singular near-atmospheric pressure relaxation with the mandated 5 s step. Simulations that exceeded 50 bar or became nonfinite during fitting were assigned a finite 50-bar continuation as a numerical penalty; this guard is not part of the delivered equation and was inactive at all retained fits.')
 family={0:'Grey-box nonlinear lumped isothermal gas-inventory model with regularized signed power-law outlet flow and an empirical rational valve characteristic. Mass-balance/ideal-gas basis: Bird, Stewart and Lightfoot, Transport Phenomena, second edition (2002), cited from memory without checking; the empirical fractional-power and rational valve laws are modeling choices, not quoted constitutive laws.',1:'Grey-box lumped isothermal gas-inventory model with mixed linear/quadratic hydraulic resistance (Darcy–Forchheimer-type pressure-loss law). The inverse resistance relation is derived explicitly below rather than asserting that the tank is a porous bed. Mass-balance/ideal-gas basis: Bird, Stewart and Lightfoot, Transport Phenomena, second edition (2002), cited from memory without checking.',2:'Grey-box lumped isothermal gas-inventory model with a regularized isentropic compressible-orifice outlet and sonic choking. Reference checked during this round: NASA Glenn Research Center, Mass Flow Choking, last updated May 13, 2021. The nozzle relation is idealized; smoothing and actuator characteristic are additional empirical approximations.'}[k]
 driving=H[k]
 commoninterp=f'`p` is absolute headspace pressure in bar, `valve` is closure in percent, and `flow` is inlet flow in L/min. The modeled derivative `dp` is in bar/s. `patm` is the atmospheric reference and `vmax` is full closure. The dimensionless opening is `{O}` and the dimensionless pressure difference is `{X}`. The source `ain*flow` is pressure accumulation from the inlet. The nonnegative aperture-dependent outlet scale is `{C}`: `cf` sets its full-open value, `expo` sets aperture curvature, and `shape` produces a saturating conductance. Clipping opening to its physical interval is a guard against out-of-range input, not a fitted feature. The signed pressure-driving factor is `{driving}`. '
 extra={0:'For pressure differences much larger than `delta`, this factor approaches a signed pressure power with exponent `power`; near atmosphere it becomes linear. `delta` is tied by `(cf/(patm*rate))**(1/(1-power))`, making the full-open atmospheric slope exactly `rate`. The fractional power is an empirical loss relation; it does not identify a specific flow regime.',1:'Writing the dimensionless outlet flux as `h`, the assumed pressure-loss relation is `((p-patm)/patm) = delta*h + h*Abs(h)`; its inverse is `2*((p-patm)/patm)/(delta+sqrt(delta**2+4*Abs((p-patm)/patm)))`. The first loss term models viscous/linear resistance, the second inertial/quadratic resistance. `delta = cf/(patm*rate)` makes the full-open atmospheric slope `rate`. The common aperture scaling is an approximation; true laminar and turbulent losses need not share the same valve factor.',2:f'`gam` is the assumed heat-capacity ratio and `rcrit` is the sonic pressure-ratio threshold. The ratio `{ratio}` selects the subsonic or choked branch. `Max(p, patm)/patm` supplies the upstream-pressure dependence. `sign(((p-patm)/patm))` reverses the flux for sub-atmospheric pressure. The factor `sqrt(Abs(((p-patm)/patm))/(Abs(((p-patm)/patm))+delta))` regularizes the ideal square-root law at atmospheric pressure; this is a finite-resistance approximation, not an exact isentropic law. The tie `delta = (2/gam)*(cf/(patm*rate))**2` makes the full-open atmospheric limiting slope `rate`.'}[k]
 physical=(' R1: exactly satisfied because the inlet-flow partial derivative is the positive `ain`. R2: satisfied for `p >= patm`, the intended overpressure operation, because the outlet scale decreases with closure while the pressure-driving factor is nonnegative. For `p < patm`, the signed reverse-flow extension does NOT satisfy R2 literally: closing the valve reduces atmospheric inflow. This is a disclosed limitation and the physically expected reversal for a bidirectional outlet; no unobserved vacuum-breaker mechanism is invented. R3: at `flow = 0` L/min and `p = patm = 1` bar, the derivative is exactly zero for any valve setting. R4: at zero inlet and an open outlet, the outlet term has the opposite sign to the pressure departure and thus relaxes toward atmosphere from either side. R5: at `valve = vmax = 100` percent, the outlet term vanishes exactly, leaving `ain*flow >= 0` for supplied nonnegative flow. These are continuous-time statements; bounded atmospheric relaxation was additionally chosen to improve numerical behavior of five-second RK4.')
 origin=('The initial families were listed before fitting: linear relaxation, signed pressure power laws, and compressible-orifice flow. The common inlet-minus-outlet structure, atmospheric reference, valve shutoff, and signed pressure relaxation came from gas conservation and physical constraints. I manually proposed opening-power and exponential valve curves, then compared derivative-initialized free-running fits using identify.py. I examined residuals using residuals.py and inspect_alignment.py: the rational saturating aperture law reduced derivative bias at low closure relative to simple opening powers. refined.py also tested an atmospheric offset and quadratic/saturating inlet terms. The quadratic term fitted essentially to zero, and the saturating inlet gave negligible validation improvement, so neither was retained. The atmospheric offset offered little validation improvement and could absorb sensor bias; `patm` was fixed to the brief instead. No genetic programming, symbolic-regression package, or sparse-regression search was run. ')
 origin += {0:'The smooth signed pressure power was a manually chosen empirical interpolation between linear near-equilibrium and fractional far-from-equilibrium losses. The final change tied its smoothing to a bounded relaxation rate, replacing an independently fitted smoothing parameter to control near-atmospheric RK4 stiffness.',1:'The mixed linear/quadratic pressure-loss law was tried as a more directly interpretable alternative to a free pressure exponent. Solving that assumed algebraic resistance law supplies the square root and absolute value, rather than obtaining them from a symbolic search. Its near-equilibrium coefficient was tied to the bounded relaxation rate for RK4 conditioning.',2:'The pressure-ratio powers and choking threshold came from the ideal isentropic nozzle law, checked against NASA Glenn, rather than numerical symbolic search. The near-atmospheric multiplier and rational actuator law were manually proposed approximations. Smoothing was tied to the atmospheric relaxation rate because an ideal square-root law alone can be stiff at the sample interval.'}[k]
 limitation=(f'Training-only free-running RMSE was {r["training_only_train_rmse"]:.6f} bar on data/train.csv and {r["training_only_val_rmse"]:.6f} bar on data/val.csv. After joint refitting, RMSE is {r["final_train_rmse"]:.6f} bar on training and {r["final_val_rmse"]:.6f} bar on validation; combined fit RMSE is {r["final_combined_rmse"]:.6f} bar. These final figures are not held-out scores. The final `rate` reaches its chosen upper bound of 0.5 1/s, so the smoothing scale is constrained partly by numerical conditioning rather than uniquely resolved by the experiment. Observed pressures cover approximately 0.992 to 2.187 bar on training and 0.994 to 2.144 bar on validation; fully sealed operation and exact zero inlet were not directly sampled. Headspace volume, temperature, flow-reference conditions, gas holdup, valve geometry, leakage and sensor bias are not separately identified. A single-state memoryless model cannot describe bubble transport, valve hysteresis, controller dynamics, or thermal drift. Increment residuals remain strongly correlated with the next sampled flow increment; this suggests timing/unmodeled dynamics but does not identify a particular delay. The one abrupt pressure drop inconsistent with the derivative column in each file was retained, as required by treating each file as a contiguous trajectory. Model assumptions should not be extrapolated to fermentation gas generation, large vacuum, changed liquid level, or different outlet hardware. A perfectly sealed tank with sustained inlet has no finite equilibrium; pressure can eventually exceed the evaluator safety interval for sufficiently long sealed runs, as real mass conservation predicts. ')
 if k==2:limitation+='The ideal nozzle law omits temperature changes and actual valve discharge-coefficient variation. The sub-atmospheric extension is only a formal bidirectional approximation; negative absolute pressures have no physical interpretation. '
 limitation+=physical
 model={'expressions':{'dp':expr},'parameters':parameters,'estimation':{'criterion':criterion,'data':data,'method':method,'script':'fit_final.py'},'discussion':{'family':family,'interpretation':commoninterp+extra,'origin':origin,'limitations':limitation}}
 Path('models/'+label+'.json').write_text(json.dumps(model,indent=2))
Path('models/pool.json').write_text(json.dumps({'order':['power_balance','mixed_resistance','compressible_nozzle'],'recommended':'power_balance','reason':'The regularized power-law gas balance had the best validation free-running error among these numerically conditioned families before the final refit (0.038653 bar), and has the lowest combined pressure RMSE after fitting both available trajectories (0.031752 bar). Its positive inlet gain, shutoff aperture law, finite atmospheric relaxation and overpressure valve monotonicity are physically interpretable. The residual timing correlation and sub-atmospheric R2 exception are disclosed; no unseen-test performance is claimed.'},indent=2))
